#include <LVRS/FontPolicy.h>
#include <future>
#include <algorithm>
#include <array>
#include <iostream>
using namespace ii;
namespace {
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
template<class T>T take(core::Result<T> value){if(!value)throw std::runtime_error(value.error().message);return std::move(*value);}
void good(core::Result<void> value){if(!value)throw std::runtime_error(value.error().message);}
struct Provider final:gui::FontProvider {
    std::vector<std::string> names{"System","Arial"};bool bundled=true,wrong_resolution=false;int loads=0;
    std::vector<std::string> families()const override{return names;}
    std::string system_family()const override{return "System";}
    std::string resolve(const gui::FontFace& face)const override{return wrong_resolution?"System":face.family;}
    gui::FontLoadReport load(std::span<const gui::FontResource> resources)override{++loads;gui::FontLoadReport result;for(const auto& resource:resources)result.resources.push_back({std::string(resource.file),bundled,bundled?"":"Missing"});if(bundled&&std::ranges::find(names,"Pretendard")==names.end())names.push_back("Pretendard");return result;}
};
struct Fixture final {
    std::shared_ptr<Provider> provider=std::make_shared<Provider>();std::shared_ptr<gui::FontDatabase> db;
    Fixture(bool bundle=true,std::optional<gui::FontFace> application=gui::FontFace{"System",600,"Italic"}){provider->bundled=bundle;db=std::make_shared<gui::FontDatabase>(provider,std::move(application));}
};
void defaults(){Fixture f;lvrs::FontPolicy p(f.db);check(p.preferredFamily()=="Pretendard"&&p.systemFamily()=="System"&&p.effectiveFamily()=="Pretendard"&&p.pretendardAvailable()&&p.lastWarning().empty(),"Default font policy values differ");check(f.db->application_font()==gui::FontFace{"Pretendard",600,"SemiBold"},"Application family/style did not preserve its weight");}
void resources(){Fixture f;lvrs::FontPolicy p(f.db);for(const auto* target:{"Arial","Helvetica","Sans Serif","Noto Sans","SF Pro Text","SF Pro Display","system-ui","sans-serif"})check(f.db->substitutions(target)==std::vector<std::string>{"Pretendard"},"Original substitution target missing");p.refresh();(void)p.enforceApplicationFallback();check(f.provider->loads==1&&gui::FontDatabase::bundled_fonts().size()==10,"Bundled font registration repeated or lost a resource");}
void missing(){Fixture f(false);lvrs::FontPolicy p(f.db);check(!p.pretendardAvailable()&&p.effectiveFamily()=="System"&&p.lastWarning().empty(),"Constructor fabricated availability or warning");check(!p.enforceApplicationFallback()&&p.lastWarning()=="Pretendard is unavailable. Falling back to application font.","Missing font warning differs");}
void no_application(){Fixture f(false,std::nullopt);lvrs::FontPolicy p(f.db);check(p.effectiveFamily()=="System"&&!p.enforceApplicationFallback()&&!f.db->application_font(),"A font policy created a missing application context");}
void preferred(){Fixture f(false);f.provider->names={"System","A Pretendard Variant","pretendard"};lvrs::FontPolicy p(f.db);check(p.effectiveFamily()=="pretendard"&&f.db->application_font()->family=="A Pretendard Variant","Exact-preferred detection and first-containing enforcement were conflated");}
void current_alias(){Fixture f(false,gui::FontFace{"My Pretendard Alias",500,"Custom"});lvrs::FontPolicy p(f.db);check(p.enforceApplicationFallback()&&p.lastWarning().empty()&&f.db->application_font()->style=="Custom","Original containing-name early success changed");}
void requested(){Fixture f;lvrs::FontPolicy p(f.db);check(p.resolveFamily(" \taRiAl \n")=="aRiAl"&&p.resolveFamily("Missing")=="Pretendard"&&p.resolveFamily("  ")=="Pretendard","Requested family spelling/fallback changed");}
void tokens(){Fixture f;lvrs::FontPolicy p(f.db);const std::array<int,7> sizes{26,22,17,15,13,12,11},weights{700,700,600,600,500,600,400};const std::array<const char*,7> styles{"Bold","Bold","SemiBold","SemiBold","Medium","SemiBold","Regular"};for(std::size_t i=0;i<sizes.size();++i)check(p.weightForTextSize(sizes[i],123)==weights[i]&&p.styleNameForTextSize(sizes[i],"Other")==styles[i]&&p.isThemeTextStyleCompliant(sizes[i],weights[i],styles[i]),"An original text token changed");}
void unknown(){Fixture f;lvrs::FontPolicy p(f.db);for(int size:{-1,0,10,14,16,18,200})check(p.weightForTextSize(size,321)==321&&p.styleNameForTextSize(size," Custom ")==" Custom "&&!p.isThemeTextStyleCompliant(size,321,"Custom"),"Unknown-size fallback was normalized or replaced");}
void compliance(){Fixture f;lvrs::FontPolicy p(f.db);check(p.isThemeTextStyleCompliant(17,600,"  sEmIbOlD ")&&!p.isThemeTextStyleCompliant(17,500,"SemiBold")&&!p.isThemeTextStyleCompliant(17,600,"Bold"),"Style compliance lost size/weight/name conjunction");}
void unicode(){Fixture f;lvrs::FontPolicy p(f.db);check(p.resolveFamily("\xc2\xa0" "Arial\xe3\x80\x80")=="Arial"&&p.isThemeTextStyleCompliant(17,600,"\xe2\x80\xafſemiBold\xc2\xa0"),"Unicode trim or style case folding changed");}
void refresh(){Fixture f(false);lvrs::FontPolicy p(f.db);f.provider->names.push_back("Pretendard");p.refresh();check(p.pretendardAvailable()&&p.effectiveFamily()=="Pretendard"&&f.db->application_font()->family=="System","Refresh did not update projection or unexpectedly applied a font");}
void events(){Fixture f(false);lvrs::FontPolicy p(f.db);std::vector<lvrs::FontPolicyEvent> events;auto port=std::make_shared<lvrs::FontPolicyChangePort>([&](auto e){events.push_back(e);});good(p.observe(port));p.refresh();check(events.empty(),"Unchanged font projection notified");check(!p.enforceApplicationFallback()&&events==std::vector{lvrs::FontPolicyEvent::last_warning},"Warning event grouping changed");events.clear();f.provider->names.push_back("Pretendard");p.refresh();check(events==std::vector{lvrs::FontPolicyEvent::effective_family},"Effective/availability values were not one group");events.clear();check(p.enforceApplicationFallback()&&events==std::vector{lvrs::FontPolicyEvent::last_warning},"Successful enforce did not clear warning independently");}
void unavailable_apply(){Fixture f;lvrs::FontPolicy p(f.db);take(f.db->set_application_font({"System",400,"Regular"}));f.provider->wrong_resolution=true;check(!p.enforceApplicationFallback()&&p.pretendardAvailable()&&p.lastWarning().empty(),"Original available-but-unapplied warning condition changed");}
void errors(){Fixture f(false);lvrs::FontPolicy p(f.db);auto port=std::make_shared<lvrs::FontPolicyChangePort>([&](auto){bool rejected=false;try{p.refresh();}catch(const std::logic_error&){rejected=true;}check(rejected,"Reentrant policy mutation admitted");throw std::runtime_error("receiver");});good(p.observe(port));f.provider->names.push_back("Pretendard");bool failed=false;try{p.refresh();}catch(...){failed=true;}check(failed&&p.pretendardAvailable(),"Receiver failure rolled back committed policy data");port.reset();p.refresh();}
void owner(){Fixture f;lvrs::FontPolicy p(f.db);check(std::async(std::launch::async,[&]{try{p.refresh();return false;}catch(const std::logic_error&){return true;}}).get(),"Foreign policy mutation admitted");}
void independent(){Fixture a,b(false);lvrs::FontPolicy one(a.db),two(b.db);check(one.pretendardAvailable()&&!two.pretendardAvailable()&&one.effectiveFamily()=="Pretendard"&&two.effectiveFamily()=="System","Independent font contexts shared policy state");}
void retirement(){Fixture f(false);auto p=std::make_unique<lvrs::FontPolicy>(f.db);int late=0;auto first=std::make_shared<lvrs::FontPolicyChangePort>([&](auto){p.reset();});auto second=std::make_shared<lvrs::FontPolicyChangePort>([&](auto){++late;});good(p->observe(first));good(p->observe(second));f.provider->names.push_back("Pretendard");auto* borrowed=p.get();borrowed->refresh();check(!p&&late==0,"A retired policy delivered a later receiver");}
}
int main(int argc,char** argv){try{const std::string name=argc>1?argv[1]:"defaults";
    if(name=="defaults")defaults();else if(name=="resources")resources();else if(name=="missing")missing();else if(name=="no_application")no_application();else if(name=="preferred")preferred();else if(name=="current_alias")current_alias();else if(name=="requested")requested();else if(name=="tokens")tokens();else if(name=="unknown")unknown();else if(name=="compliance")compliance();else if(name=="unicode")unicode();else if(name=="refresh")refresh();else if(name=="events")events();else if(name=="unavailable_apply")unavailable_apply();else if(name=="errors")errors();else if(name=="owner")owner();else if(name=="independent")independent();else if(name=="retirement")retirement();else throw std::runtime_error("Unknown native font policy case");std::cout<<"Native font policy "<<name<<" passed\n";
}catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
